PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a energia:OperatorChange ;
     energia:previousCompany ?p ;
     energia:newCompany ?q .
  FILTER(?p != ?q)
  FILTER NOT EXISTS {
    ?p energia:name ?pn . ?q energia:name ?qn .
    FILTER(CONTAINS(UCASE(?pn), "GEOPARK") && CONTAINS(UCASE(?qn), "GEOPARK"))
  }
}
